const widget: Product = { id: "w1", name: "Widget", unitPriceCents: 1000 };
const gadget: Product = { id: "g1", name: "Gadget", unitPriceCents: 2000, weightGrams: 500 };

describe("Cart — line management", () => {
  it("starts with zero items", () => {
    const cart = new Cart();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("adds a product", () => {
    const cart = new Cart();
    cart.add(widget, 3);
    expect(cart.itemCount).toBe(3);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0]!.product.id).toBe("w1");
    expect(snap[0]!.quantity).toBe(3);
  });

  it("merges quantity when adding same product twice", () => {
    const cart = new Cart();
    cart.add(widget, 2);
    cart.add(widget, 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.snapshot()).toHaveLength(1);
    expect(cart.snapshot()[0]!.quantity).toBe(5);
  });

  it("keeps separate entries for different products", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    cart.add(gadget, 2);
    expect(cart.itemCount).toBe(3);
    expect(cart.snapshot()).toHaveLength(2);
  });

  it("rejects non-positive quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(widget, 0)).toThrow(RangeError);
    expect(() => cart.add(widget, -1)).toThrow(RangeError);
  });

  it("rejects non-integer quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(widget, 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents", () => {
    const cart = new Cart();
    const bad: Product = { id: "bad", name: "Bad", unitPriceCents: -10 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("removes a product and returns true", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    expect(cart.remove("w1")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("unknown")).toBe(false);
  });

  it("updates quantity of existing product", () => {
    const cart = new Cart();
    cart.add(widget, 5);
    cart.updateQuantity("w1", 2);
    expect(cart.itemCount).toBe(2);
  });

  it("updateQuantity(0) removes the product", () => {
    const cart = new Cart();
    cart.add(widget, 3);
    cart.updateQuantity("w1", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toHaveLength(0);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("nope", 5)).toThrow("not in the cart");
  });

  it("updateQuantity rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    expect(() => cart.updateQuantity("w1", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    expect(() => cart.updateQuantity("w1", 2.5)).toThrow(RangeError);
  });

  it("clears all items", () => {
    const cart = new Cart();
    cart.add(widget, 2);
    cart.add(gadget, 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("snapshot returns a deep copy", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const snap = cart.snapshot();
    snap[0]!.quantity = 999;
    snap[0]!.product.unitPriceCents = 0;
    // Cart should be unaffected
    expect(cart.snapshot()[0]!.quantity).toBe(1);
    expect(cart.snapshot()[0]!.product.unitPriceCents).toBe(1000);
  });
});

describe("Cart — pricing pipeline (totals)", () => {
  it("computes subtotal from lines", () => {
    const cart = new Cart();
    cart.add(widget, 2); // 2 * 1000 = 2000
    cart.add(gadget, 1); // 1 * 2000 = 2000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(4000);
  });

  it("empty cart returns all zeros", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("applies discount policy and clamps to [0, subtotal]", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(widget, 1); // subtotal = 1000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(1000);
    expect(totals.discountCents).toBe(500);
    expect(discountPolicy.computeDiscountCents).toHaveBeenCalledWith(1000);
  });

  it("clamps negative discount to 0", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(widget, 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("clamps discount exceeding subtotal to subtotal", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(9999),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(widget, 1); // subtotal = 1000
    expect(cart.totals().discountCents).toBe(1000);
  });

  it("applies tax on discounted subtotal", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(50),
    };
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const cart = new Cart({ discountPolicy, taxCalculator, region: "US-CA" });
    cart.add(widget, 1); // subtotal = 1000, discount = 200, discounted = 800
    const totals = cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
    expect(totals.taxCents).toBe(50);
  });

  it("clamps negative tax to 0", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-10),
    };
    const cart = new Cart({ taxCalculator });
    cart.add(widget, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("applies shipping on discounted subtotal", () => {
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(599),
    };
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(300),
    };
    const cart = new Cart({ discountPolicy, shippingCalculator });
    cart.add(widget, 1); // subtotal = 1000, discounted = 700
    const totals = cart.totals();
    expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      700,
    );
    expect(totals.shippingCents).toBe(599);
  });

  it("clamps negative shipping to 0", () => {
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-5),
    };
    const cart = new Cart({ shippingCalculator });
    cart.add(widget, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(100),
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(72),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(599),
    };
    const cart = new Cart({ discountPolicy, taxCalculator, shippingCalculator });
    cart.add(widget, 1); // subtotal 1000, discount 100, discounted 900
    const totals = cart.totals();
    expect(totals.totalCents).toBe(900 + 72 + 599);
  });

  it("defaults to NoDiscountPolicy, NoTaxCalculator, FreeShipping, region US", () => {
    const cart = new Cart();
    cart.add(widget, 2); // subtotal = 2000
    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(2000);
  });
});

describe("Cart — async checkout", () => {
  it("returns totals and lines without collaborators", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.lines).toHaveLength(1);
  });

  it("refreshes prices via PriceFetcher", async () => {
    const cart = new Cart();
    cart.add(widget, 2);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });
    expect(result.totals.subtotalCents).toBe(3000); // 2 * 1500
    expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
  });

  it("validates inventory and passes when available", async () => {
    const cart = new Cart();
    cart.add(widget, 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
    expect(inventoryChecker.check).toHaveBeenCalledWith("w1", 2);
  });

  it("throws InventoryError when item unavailable", async () => {
    const cart = new Cart();
    cart.add(widget, 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        reason: "sold out",
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("w1");
      expect(invErr.requested).toBe(5);
      expect(invErr.message).toBe("sold out");
    }
  });

  it("throws InventoryError on partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(widget, 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      } satisfies InventoryDecision),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("w1");
      expect(invErr.requested).toBe(10);
      expect(invErr.available).toBe(3);
    }
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const taxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };
    const cart = new Cart({ region: "US" });
    cart.add(widget, 1); // subtotal 1000, no discount → taxable 1000
    const result = await cart.checkout({ asyncTaxProvider: taxProvider });
    // 10% of 1000 = 100
    expect(result.totals.taxCents).toBe(100);
    expect(taxProvider.getRate).toHaveBeenCalledWith("US");
  });

  it("async checkout with discount + async tax + shipping", async () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const taxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08),
    };
    const cart = new Cart({ discountPolicy, shippingCalculator, region: "US-TX" });
    cart.add(widget, 2); // subtotal 2000, discount 200, discounted 1800
    const result = await cart.checkout({ asyncTaxProvider: taxProvider });
    // tax: 8% of 1800 = 144
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.totals.discountCents).toBe(200);
    expect(result.totals.taxCents).toBe(144);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(1800 + 144 + 500);
  });

  it("async tax provider rejection propagates", async () => {
    const taxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("rate service down")),
    };
    const cart = new Cart();
    cart.add(widget, 1);
    await expect(cart.checkout({ asyncTaxProvider: taxProvider })).rejects.toThrow(
      "rate service down",
    );
  });

  it("price fetcher rejection propagates", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price API down")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow("price API down");
  });

  it("checks inventory after refreshing prices", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(2000),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ priceFetcher, inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
    expect(inventoryChecker.check).toHaveBeenCalledWith("w1", 1);
  });

  it("first inventory denial wins when multiple items", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    cart.add(gadget, 2);
    const inventoryChecker: InventoryChecker = {
      check: vi
        .fn()
        .mockResolvedValueOnce({ available: true } satisfies InventoryDecision)
        .mockResolvedValueOnce({
          available: false,
          reason: "gadget out",
        } satisfies InventoryDecision),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      expect((err as InventoryError).productId).toBe("g1");
    }
  });

  it("checkout with all collaborators", async () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(100),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(300),
    };
    const cart = new Cart({ discountPolicy, shippingCalculator, region: "FR" });
    cart.add(widget, 2);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1200),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.20),
    };

    const result = await cart.checkout({ priceFetcher, inventoryChecker, asyncTaxProvider });
    // subtotal: 2 * 1200 = 2400, discount 100, discounted 2300
    // tax: 20% of 2300 = 460, shipping 300
    expect(result.totals.subtotalCents).toBe(2400);
    expect(result.totals.discountCents).toBe(100);
    expect(result.totals.taxCents).toBe(460);
    expect(result.totals.shippingCents).toBe(300);
    expect(result.totals.totalCents).toBe(2300 + 460 + 300);
    expect(result.lines).toHaveLength(1);
    expect(result.lines[0]!.product.unitPriceCents).toBe(1200);
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([0, 100, 99999])("returns 0 for subtotal %i", (subtotal) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, 101, NaN, Infinity, -Infinity])(
      "rejects out-of-range percent %s",
      (pct) => {
        expect(() => new PercentageDiscountPolicy(pct)).toThrow(RangeError);
      },
    );

    it.each([0, 50, 100])("accepts valid percent %i", (pct) => {
      expect(() => new PercentageDiscountPolicy(pct)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 10000 as 1000", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(10000)).toBe(1000);
    });

    it("rounds down to nearest cent (floors)", () => {
      // 33% of 100 = 33.0 exactly
      expect(new PercentageDiscountPolicy(33).computeDiscountCents(100)).toBe(33);
      // 10% of 999 = 99.9 → floor to 99
      expect(new PercentageDiscountPolicy(10).computeDiscountCents(999)).toBe(99);
    });

    it("100% discount returns full subtotal", () => {
      expect(new PercentageDiscountPolicy(100).computeDiscountCents(5000)).toBe(5000);
    });

    it("0% discount returns 0", () => {
      expect(new PercentageDiscountPolicy(0).computeDiscountCents(5000)).toBe(0);
    });

    it("returns 0 for zero subtotal", () => {
      expect(new PercentageDiscountPolicy(50).computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      expect(new PercentageDiscountPolicy(50).computeDiscountCents(-1000)).toBe(0);
    });

    it("handles very large subtotal", () => {
      expect(new PercentageDiscountPolicy(25).computeDiscountCents(1_000_000_00)).toBe(25_000_000);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });

    it("accepts positive integer", () => {
      expect(() => new FixedAmountDiscountPolicy(500)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns fixed amount when subtotal exceeds it", () => {
      expect(new FixedAmountDiscountPolicy(500).computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when fixed amount exceeds subtotal", () => {
      expect(new FixedAmountDiscountPolicy(2000).computeDiscountCents(500)).toBe(500);
    });

    it("returns subtotal when fixed amount equals subtotal", () => {
      expect(new FixedAmountDiscountPolicy(500).computeDiscountCents(500)).toBe(500);
    });

    it("returns 0 for zero subtotal", () => {
      expect(new FixedAmountDiscountPolicy(500).computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      expect(new FixedAmountDiscountPolicy(500).computeDiscountCents(-100)).toBe(0);
    });

    it("zero discount returns 0", () => {
      expect(new FixedAmountDiscountPolicy(0).computeDiscountCents(5000)).toBe(0);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });

    it("accepts single policy", () => {
      expect(() => new CompositeDiscountPolicy([new NoDiscountPolicy()])).not.toThrow();
    });
  });

  describe("sum mode", () => {
    it("sums discount from multiple policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 10000 = 1000
          new FixedAmountDiscountPolicy(500), // 500
        ],
        "sum",
      );
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("both policies see the original subtotal in sum mode", () => {
      // Two 50% policies in sum mode: each sees 10000, returns 5000 → total 10000
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(10000)).toBe(10000);
    });

    it("clamps negative individual results to 0 before summing", () => {
      // NoDiscountPolicy returns 0, not negative
      const composite = new CompositeDiscountPolicy(
        [new NoDiscountPolicy(), new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(500)).toBe(100);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("defaults to sum mode when not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      // 10% of 5000 = 500, plus 200 = 700
      expect(composite.computeDiscountCents(5000)).toBe(700);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      // 10% of 10000 = 1000 → remaining 9000, then fixed 500 → total 1500
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10),
          new FixedAmountDiscountPolicy(500),
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("ordering matters in chain mode", () => {
      // Fixed 500 first → remaining 9500, then 10% of 9500 = 950 → total 1450
      const compositeFixedFirst = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(500),
          new PercentageDiscountPolicy(10),
        ],
        "chain",
      );
      expect(compositeFixedFirst.computeDiscountCents(10000)).toBe(1450);

      // Percentage first → 1000 off → remaining 9000, then 500 → total 1500
      const compositePctFirst = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10),
          new FixedAmountDiscountPolicy(500),
        ],
        "chain",
      );
      expect(compositePctFirst.computeDiscountCents(10000)).toBe(1500);
    });

    it("chain cannot exceed subtotal", () => {
      // 50% of 1000 = 500, remaining 500; 50% of 500 = 250, remaining 250 → total 750
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(750);
    });

    it("stops accumulating when remaining reaches 0", () => {
      // 100% of 1000 = 1000, remaining 0; second policy gets 0 → total 1000
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(100), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine } from "../src/product.ts";

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it("returns 0 regardless of inputs", () => {
    expect(calc.computeTaxCents(10000, "US")).toBe(0);
    expect(calc.computeTaxCents(0, "FR")).toBe(0);
    expect(calc.computeTaxCents(99999, "GB")).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it.each([-0.01, 1.01, NaN, Infinity])(
      "rejects defaultRate %s",
      (rate) => {
        expect(() => new RegionalTaxCalculator({}, rate)).toThrow(RangeError);
      },
    );

    it("rejects invalid rate in rates map", () => {
      expect(() => new RegionalTaxCalculator({ "US": 1.5 })).toThrow(RangeError);
    });

    it("rejects negative rate in rates map", () => {
      expect(() => new RegionalTaxCalculator({ "US": -0.1 })).toThrow(RangeError);
    });

    it("accepts valid rates", () => {
      expect(() => new RegionalTaxCalculator({ "US": 0.08, "CA": 0.13 }, 0.05)).not.toThrow();
    });

    it("accepts zero default rate", () => {
      expect(() => new RegionalTaxCalculator({}, 0)).not.toThrow();
    });

    it("accepts rate of exactly 1", () => {
      expect(() => new RegionalTaxCalculator({ "XX": 1 }, 1)).not.toThrow();
    });
  });

