{"path": "/tmp/sv-07a3cf11d9a049a7a5026a53ec40c2ac/fixtures/typescript-vitest-cart/tests/cart.test.ts", "file_text": "import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
