    cart.add(widget, 1); // subtotal 1000, no discount → taxable 1000
    const result = await cart.checkout({ asyncTaxProvider: taxProvider });
    // 10% of 1000 = 100
    expect(result.totals.taxCents).toBe(100);
    expect(taxProvider.getRate).toHaveBeenCalledWith("US");
