      getRate: vi.fn().mockResolvedValue(0.08),
    };
    const cart = new Cart({ discountPolicy, shippingCalculator, region: "US-TX" });
    cart.add(widget, 2); // subtotal 2000, discount 200, discounted 1800
    const result = await cart.checkout({ asyncTaxProvider: taxProvider });
    // tax: 8% of 1800 = 144
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.totals.discountCents).toBe(200);
    expect(result.totals.taxCents).toBe(144);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(1800 + 144 + 500);
