import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([0, 100, 99999])("returns 0 for subtotal %i", (subtotal) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, 101, NaN, Infinity, -Infinity])(
      "rejects out-of-range percent %s",
      (pct) => {
        expect(() => new PercentageDiscountPolicy(pct)).toThrow(RangeError);
      },
    );

    it.each([0, 50, 100])("accepts valid percent %i", (pct) => {
      expect(() => new PercentageDiscountPolicy(pct)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 10000 as 1000", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(10000)).toBe(1000);
    });

    it("rounds down to nearest cent (floors)", () => {
      // 33% of 100 = 33.0 exactly
      expect(new PercentageDiscountPolicy(33).computeDiscountCents(100)).toBe(33);
      // 10% of 999 = 99.9 → floor to 99
      expect(new PercentageDiscountPolicy(10).computeDiscountCents(999)).toBe(99);
    });

    it("100% discount returns full subtotal", () => {
      expect(new PercentageDiscountPolicy(100).computeDiscountCents(5000)).toBe(5000);
    });

    it("0% discount returns 0", () => {
      expect(new PercentageDiscountPolicy(0).computeDiscountCents(5000)).toBe(0);
    });

    it("returns 0 for zero subtotal", () => {
      expect(new PercentageDiscountPolicy(50).computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      expect(new PercentageDiscountPolicy(50).computeDiscountCents(-1000)).toBe(0);
    });

    it("handles very large subtotal", () => {
      expect(new PercentageDiscountPolicy(25).computeDiscountCents(1_000_000_00)).toBe(25_000_000);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });

    it("accepts positive integer", () => {
      expect(() => new FixedAmountDiscountPolicy(500)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns fixed amount when subtotal exceeds it", () => {
      expect(new FixedAmountDiscountPolicy(500).computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when fixed amount exceeds subtotal", () => {
      expect(new FixedAmountDiscountPolicy(2000).computeDiscountCents(500)).toBe(500);
    });

    it("returns subtotal when fixed amount equals subtotal", () => {
      expect(new FixedAmountDiscountPolicy(500).computeDiscountCents(500)).toBe(500);
    });

    it("returns 0 for zero subtotal", () => {
      expect(new FixedAmountDiscountPolicy(500).computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      expect(new FixedAmountDiscountPolicy(500).computeDiscountCents(-100)).toBe(0);
    });

    it("zero discount returns 0", () => {
      expect(new FixedAmountDiscountPolicy(0).computeDiscountCents(5000)).toBe(0);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });

    it("accepts single policy", () => {
      expect(() => new CompositeDiscountPolicy([new NoDiscountPolicy()])).not.toThrow();
    });
  });

  describe("sum mode", () => {
    it("sums discount from multiple policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 10000 = 1000
          new FixedAmountDiscountPolicy(500), // 500
        ],
        "sum",
      );
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("both policies see the original subtotal in sum mode", () => {
      // Two 50% policies in sum mode: each sees 10000, returns 5000 → total 10000
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(10000)).toBe(10000);
    });

    it("clamps negative individual results to 0 before summing", () => {
      // NoDiscountPolicy returns 0, not negative
      const composite = new CompositeDiscountPolicy(
        [new NoDiscountPolicy(), new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(500)).toBe(100);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("defaults to sum mode when not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      // 10% of 5000 = 500, plus 200 = 700
      expect(composite.computeDiscountCents(5000)).toBe(700);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      // 10% of 10000 = 1000 → remaining 9000, then fixed 500 → total 1500
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10),
          new FixedAmountDiscountPolicy(500),
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("ordering matters in chain mode", () => {
      // Fixed 500 first → remaining 9500, then 10% of 9500 = 950 → total 1450
      const compositeFixedFirst = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(500),
          new PercentageDiscountPolicy(10),
        ],
        "chain",
      );
      expect(compositeFixedFirst.computeDiscountCents(10000)).toBe(1450);

      // Percentage first → 1000 off → remaining 9000, then 500 → total 1500
      const compositePctFirst = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10),
          new FixedAmountDiscountPolicy(500),
        ],
        "chain",
      );
      expect(compositePctFirst.computeDiscountCents(10000)).toBe(1500);
    });

    it("chain cannot exceed subtotal", () => {
      // 50% of 1000 = 500, remaining 500; 50% of 500 = 250, remaining 250 → total 750
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(750);
    });

    it("stops accumulating when remaining reaches 0", () => {
      // 100% of 1000 = 1000, remaining 0; second policy gets 0 → total 1000
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(100), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

