+      const compositePctFirst = new CompositeDiscountPolicy(
+        [
+          new PercentageDiscountPolicy(10),
+          new FixedAmountDiscountPolicy(500),
+        ],
+        "chain",
+      );
+      expect(compositePctFirst.computeDiscountCents(10000)).toBe(1500);
+    });
