+    it("stops accumulating when remaining reaches 0", () => {
+      // 100% of 1000 = 1000, remaining 0; second policy gets 0 → total 1000
+      const composite = new CompositeDiscountPolicy(
+        [new PercentageDiscountPolicy(100), new FixedAmountDiscountPolicy(500)],
+        "chain",
